CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), email text NOT NULL, name text NOT NULL, UNIQUE (workspace_id, email));
CREATE TABLE companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, industry text, website text, phone text, location text, stage text NOT NULL DEFAULT 'prospect' CHECK (stage IN ('prospect','qualified','proposal','negotiation','customer','inactive')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), company_id uuid REFERENCES companies(id) ON DELETE SET NULL, owner_id uuid NOT NULL REFERENCES users(id), first_name text NOT NULL, last_name text NOT NULL, job_title text, email text, phone text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), company_id uuid REFERENCES companies(id) ON DELETE CASCADE, contact_id uuid REFERENCES contacts(id) ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK (company_id IS NOT NULL OR contact_id IS NOT NULL));
CREATE TABLE activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), company_id uuid REFERENCES companies(id) ON DELETE CASCADE, contact_id uuid REFERENCES contacts(id) ON DELETE CASCADE, owner_id uuid NOT NULL REFERENCES users(id), type text NOT NULL CHECK (type IN ('call','email','meeting','follow_up','task')), subject text NOT NULL, due_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, UNIQUE (workspace_id, name));
CREATE TABLE company_tags (company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE, tag_id uuid NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY (company_id, tag_id));
CREATE INDEX company_search_idx ON companies (workspace_id, lower(name));
CREATE INDEX activity_followup_idx ON activities (workspace_id, completed_at, due_at);
